{"file_path":"/work/tests/test_spec.py","content":""""Regression tests for the behavior defined in SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_in_denominator():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"a": [], "b": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    rate = pooled_flag_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 8, 7), ([], 3, 0), ([], 0, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_and_field_whitespace():
    assert parse_transcript_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \t"]) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": -2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "#comment", " \t# comment,not,a,record", "a,1,0"]
    assert parse_transcript_log(iter(lines)) == [{"id": "a", "day": 1, "flagged": False}]
    assert parse_transcript_log(lines[:-1]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_transcript_log_errors_include_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", " \t", "ok,1,1", bad_line])


def test_dedupe_transcripts_last_duplicate_id_wins_and_result_is_sorted():
    events = [
        {"id": "b", "day": 10, "flagged": True},
        {"id": "c", "day": 0, "flagged": True},
        {"id": "a", "day": 2, "flagged": None},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 1, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[4], events[2], events[3]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_zero_filled_and_range_filtered():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
        {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (4, 2), (20, 2)])
def test_monitor_summary_pooled_rounded_calendar_window_and_nonempty_groups(days, recent):
    groups = {
        "a": [{"day": 1, "flagged": True}],
        "b": [
            {"day": 3, "flagged": True},
            {"day": 4, "flagged": False},
            {"day": 4, "flagged": None},
            {"day": 4, "flagged": False},
            {"day": 4, "flagged": False},
        ],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_filters_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "empty": [],
        "a": [{"flagged": True}, {"flagged": False}],
        "best": [{"flagged": True}],
        "zero": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 2) == ["best", "a"]
    assert top_flagged_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 2) == []
    assert top_flagged_groups({}, 2) == []


def test_flag_rate_by_group_sorted_keys_and_empty_groups():
    groups = {
        "z": [],
        "b": [{"flagged": True}, {"flagged": None}],
        "a": [{"flagged": False}],
    }
    rates = flag_rate_by_group(groups)
    assert rates == {"a": 0.0, "b": 0.5, "z": None}
    assert list(rates) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, 0, -2], 0), ([1, 2, 3], 3),
     ([1, 2, 0, 3, 4, 5, 0, 1], 3), ([1, -1, 2], 1), ([0, 1, 2], 2)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
